"""Candidate-authored tests (supplementary evidence only)."""

import unittest
from datetime import date


class FakeRecord:
    def __init__(self, record_id, values):
        self.id = record_id
        self.revision = 1
        self.values = values


class FakeRecords:
    def __init__(self):
        self.saved = []

    def create(self, collection, values):
        record = FakeRecord("note-%d" % (len(self.saved) + 1), values)
        self.saved.append((collection, record))
        return record

    def all(self, collection):
        return [record for name, record in self.saved if name == collection]


class FakeContext:
    def __init__(self, day=date(2026, 9, 26)):
        self.records = FakeRecords()
        self._day = day

    def today(self):
        return self._day


class AddNote(unittest.TestCase):
    def test_saves_the_note_with_todays_date(self):
        import notes_app.handlers as handlers

        ctx = FakeContext()
        output = handlers.add_note(ctx, title="Buy milk")

        self.assertEqual(output, {"id": "note-1", "revision": 1})
        self.assertEqual(
            [record.values for _, record in ctx.records.saved],
            [{"title": "Buy milk", "noted_on": "2026-09-26"}],
        )

    def test_trims_surrounding_spaces(self):
        import notes_app.handlers as handlers

        ctx = FakeContext()
        handlers.add_note(ctx, title="  Call the plumber  ")

        self.assertEqual(ctx.records.all("notes")[0].values["title"], "Call the plumber")

    def test_refuses_a_blank_note_and_stores_nothing(self):
        import notes_app.handlers as handlers

        ctx = FakeContext()
        for blank in ("", "   "):
            with self.assertRaises(ValueError):
                handlers.add_note(ctx, title=blank)
        self.assertEqual(ctx.records.saved, [])


class CountNotes(unittest.TestCase):
    def test_counts_every_saved_note(self):
        import notes_app.handlers as handlers

        ctx = FakeContext()
        self.assertEqual(handlers.count_notes(ctx), {"count": 0})

        handlers.add_note(ctx, title="Buy milk")
        self.assertEqual(handlers.count_notes(ctx), {"count": 1})


if __name__ == "__main__":
    unittest.main()

