// The notes screen: a quick entry at the top, the latest notes below.
import { StrictMode, useEffect, useState } from "react";
import { createRoot } from "react-dom/client";
import "@alpha/ui-kit/styles.css";
import {
  AlphaApp,
  ErrorState,
  MetricCard,
  OperationStatus,
  Page,
  QuickEntry,
  RecordTable,
  Section,
  Stack,
  formatDay,
  useAction,
  useView,
  type RecordRow,
} from "@alpha/ui-kit";

type Note = { title: string; noted_on: string };

function App() {
  const add = useAction("add_note");
  const counter = useAction("count_notes");
  const recent = useView<Note>("notes.recent", { limit: 20 });
  const [saved, setSaved] = useState<number | null>(null);
  const [counted, setCounted] = useState(0);

  useEffect(() => {
    let current = true;
    counter
      .run({})
      .then((output) => {
        const value = (output as unknown as { count?: number } | undefined)?.count;
        if (current) setSaved(typeof value === "number" ? value : null);
      })
      .catch(() => {
        if (current) setSaved(null);
      });
    return () => {
      current = false;
    };
    // counted again once the notes have loaded and after every saved note
  }, [counted, recent.loading]);

  return (
    <Page title="Notes" description="Write a short note; it is saved with today's date.">
      <Section title="Write a note">
        <Stack>
          <QuickEntry
            label="Note"
            parse={(text) =>
              text.trim()
                ? { status: "ok", value: text.trim(), summary: text.trim() }
                : { status: "empty" }
            }
            onSubmit={async (title) => {
              await add.run({ title });
              setCounted((value) => value + 1);
            }}
          />
          <OperationStatus state={add.state} error={add.error} />
        </Stack>
      </Section>

      <Section title="How many I have saved">
        <MetricCard label="Notes saved" value={saved} hint="Everything saved so far." />
      </Section>

      <Section title="Latest notes">
        {recent.error ? (
          <ErrorState
            title="Your notes could not be loaded"
            message="Something went wrong while reading your notes. Try again."
            onRetry={recent.refresh}
          />
        ) : (
          <RecordTable<RecordRow<Note>>
            columns={[
              { id: "title", header: "Note", cell: (row) => row.values.title },
              { id: "day", header: "Day", cell: (row) => formatDay(row.values.noted_on) },
            ]}
            rows={recent.records}
            getRowId={(row) => row.id}
            getRowLabel={(row) => row.values.title}
            loading={recent.loading}
            empty={{ title: "No notes yet", message: "Write your first note above." }}
          />
        )}
      </Section>
    </Page>
  );
}

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <AlphaApp>
      <App />
    </AlphaApp>
  </StrictMode>,
);

