// The notes screen: write a short note at the top, see the latest notes below.
import { Component, StrictMode, useEffect, useRef, useState } from "react";
import type { ReactNode } from "react";
import { createRoot } from "react-dom/client";
import "@alpha/ui-kit/styles.css";
import {
  AlphaApp,
  Button,
  EmptyState,
  ErrorState,
  Form,
  MetricCard,
  Page,
  RecordTable,
  Section,
  Stack,
  TextField,
  formatDay,
  useAction,
  useView,
} from "@alpha/ui-kit";

type SafeProps = { fallback: ReactNode; children: ReactNode };

// Keeps one part of the screen from taking the whole page down with it.
class Safe extends Component<SafeProps, { failed: boolean }> {
  constructor(props: SafeProps) {
    super(props);
    this.state = { failed: false };
  }

  static getDerivedStateFromError() {
    return { failed: true };
  }

  render() {
    return this.state.failed ? this.props.fallback : this.props.children;
  }
}

function typedText(next: unknown): string {
  if (typeof next === "string") return next;
  if (next && typeof next === "object") {
    const target = (next as { target?: { value?: unknown } }).target;
    if (target && typeof target.value === "string") return target.value;
  }
  return "";
}

function noteTitle(row: any): string {
  const title = row?.values?.title ?? row?.title;
  return typeof title === "string" ? title : "";
}

function noteDay(row: any): string {
  const day = row?.values?.noted_on ?? row?.noted_on;
  if (typeof day !== "string" || !day) return "";
  try {
    const shown = formatDay(day);
    return typeof shown === "string" && shown ? shown : day;
  } catch {
    return day;
  }
}

const columns: any[] = [
  { id: "title", field: "title", header: "What you wrote", label: "What you wrote", cell: noteTitle, render: noteTitle },
  { id: "noted_on", field: "noted_on", header: "Saved on", label: "Saved on", cell: noteDay, render: noteDay },
];

function PlainNotes({ rows }: { rows: any[] }) {
  if (rows.length === 0) {
    return <p>No notes yet. Write your first note above.</p>;
  }
  return (
    <table>
      <thead>
        <tr>
          <th scope="col">What you wrote</th>
          <th scope="col">Saved on</th>
        </tr>
      </thead>
      <tbody>
        {rows.map((row, index) => (
          <tr key={row?.id ?? index}>
            <td>{noteTitle(row)}</td>
            <td>{noteDay(row)}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function App() {
  const notes = useView("notes.recent", { limit: 20 });
  const add = useAction("add_note");
  const counter = useAction("count_notes");

  const [text, setText] = useState("");
  const [problem, setProblem] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [savedCount, setSavedCount] = useState<number | null>(null);
  const [countToken, setCountToken] = useState(0);

  const runCount = useRef(counter.run);
  useEffect(() => {
    runCount.current = counter.run;
  });

  // Ask for the total once the screen opens and again after every saved note.
  useEffect(() => {
    let active = true;
    Promise.resolve()
      .then(() => runCount.current({}))
      .then((output: any) => {
        if (!active) return;
        const value = output?.count;
        setSavedCount(typeof value === "number" ? value : null);
      })
      .catch(() => {
        if (active) setSavedCount(null);
      });
    return () => {
      active = false;
    };
  }, [countToken]);

  const save = async () => {
    const title = text.trim();
    if (!title) {
      setProblem("Write a few words before saving the note.");
      return;
    }
    setProblem(null);
    setSaving(true);
    try {
      await add.run({ title });
      setText("");
      setCountToken((token) => token + 1);
      try {
        notes.refresh();
      } catch {
        // the list refreshes itself after a successful save
      }
    } catch {
      // keep what was typed so it can be saved again
      setProblem("Your note was not saved. Your words are still here — try again.");
    } finally {
      setSaving(false);
    }
  };

  const rows: any[] = (notes.records as any[]) ?? [];
  const readFailed = Boolean(notes.error);

  return (
    <Page title="Notes" description="Write a short note and it is saved with today's date.">
      <Section title="Write a note">
        <Form label="Write a note" onSubmit={save}>
          <Stack>
            <TextField
              label="Note"
              name="note"
              value={text}
              onChange={(next: unknown) => setText(typedText(next))}
              hint="Saved with today's date when you press Enter."
            />
            {problem ? <p role="alert">{problem}</p> : null}
            <Button type="submit" variant="primary" busy={saving} busyLabel="Saving…">
              Save note
            </Button>
          </Stack>
        </Form>
      </Section>

      <Section title="How many notes you have saved">
        <Safe
          fallback={
            <p>{savedCount === null ? "The total is not available yet." : `${savedCount} notes saved so far.`}</p>
          }
        >
          <MetricCard label="Notes saved" value={savedCount} hint="Everything you have saved so far." />
        </Safe>
      </Section>

      <Section title="Latest notes">
        <Safe
          fallback={
            readFailed ? (
              <p role="alert">Your notes could not be loaded. Try again in a moment.</p>
            ) : (
              <PlainNotes rows={rows} />
            )
          }
        >
          {readFailed ? (
            <div role="alert">
              <ErrorState
                title="Your notes could not be loaded"
                message="Something went wrong while reading your notes. Try again in a moment."
                onRetry={notes.refresh}
              />
            </div>
          ) : notes.loading && rows.length === 0 ? (
            <p>Loading your notes…</p>
          ) : rows.length === 0 ? (
            <EmptyState title="No notes yet" message="Write your first note above." />
          ) : (
            <RecordTable
              columns={columns}
              rows={rows}
              getRowId={(row: any) => row?.id ?? noteTitle(row)}
              getRowLabel={(row: any) => noteTitle(row)}
            />
          )}
        </Safe>
      </Section>
    </Page>
  );
}

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <AlphaApp>
      <App />
    </AlphaApp>
  </StrictMode>,
);
